<?php $labels=['draft'=>'Rascunho','pending'=>'Solicitação recebida','under_review'=>'Em análise','approved'=>'Conta atacadista aprovada','rejected'=>'Correções necessárias','suspended'=>'Acesso suspenso','cancelled'=>'Solicitação cancelada'];$descriptions=['pending'=>'Nossa equipe recebeu seus dados e iniciará a conferência.','under_review'=>'Um administrador está verificando seus dados e documentos.','approved'=>'Você já pode visualizar preços e condições exclusivas de atacado.','rejected'=>'Ajuste as informações indicadas e reenvie o cadastro.','suspended'=>'O acesso atacadista está temporariamente indisponível.']; ?>
<section class="wholesale-status wholesale-status--<?=e($account['status'])?>"><div class="status-icon"><?= $account['status']==='approved'?'✓':($account['status']==='rejected'?'!':'⌛') ?></div><span class="eyebrow">TUFFER ATACADO</span><h2><?=e($labels[$account['status']]??'Cadastro atacadista')?></h2><p><?=e($descriptions[$account['status']]??'Continue preenchendo seus dados para enviar a solicitação.')?></p><div class="company-chip"><strong><?=e($account['trade_name'])?></strong><span data-format-cnpj><?=e($account['cnpj'])?></span></div><?php if(in_array($account['status'],['draft','rejected','cancelled'],true)):?><a class="button button--primary" href="<?=e(url('/minha-conta/atacado/solicitar'))?>"><?= $account['status']==='rejected'?'Corrigir e reenviar':'Continuar cadastro' ?></a><?php endif;?></section>
<?php if(!empty($account['rejection_reason'])):?><section class="panel correction-panel"><small>ORIENTAÇÃO DA ANÁLISE</small><h3>O que precisa ser corrigido</h3><p><?=nl2br(e($account['rejection_reason']))?></p></section><?php endif;?>
<section class="panel"><div class="panel-head"><div><small>HISTÓRICO</small><h3>Acompanhamento da solicitação</h3></div></div><div class="status-timeline"><?php foreach($history as $item):?><div><i></i><span><strong><?=e($labels[$item['new_status']]??$item['new_status'])?></strong><small><?=date('d/m/Y H:i',strtotime($item['created_at']))?><?=!empty($item['changed_by_name'])?' · '.e($item['changed_by_name']):''?></small><?php if($item['reason']):?><p><?=e($item['reason'])?></p><?php endif;?></span></div><?php endforeach;?></div></section>
